std::string to_utf8(const std::wstring& s){if(s.empty())return{};int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0,nullptr,nullptr);if(n<=0)return{};std::string r((size_t)n,'\0');WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),r.data(),n,nullptr,nullptr);return r;}
std::wstring to_wide(const std::string& s){if(s.empty())return{};int n=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),nullptr,0);if(n<=0)return L"";std::wstring r((size_t)n,L'\0');MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,s.data(),(int)s.size(),r.data(),n);return r;}
std::wstring text_of(HWND h){auto n=GetWindowTextLengthW(h);std::wstring s((size_t)n+1,L'\0');GetWindowTextW(h,s.data(),n+1);s.resize(wcslen(s.c_str()));return s;}
void message(const std::wstring& s){MessageBoxW(main_window,s.c_str(),L"KR Mycelia Memory",MB_OK|MB_ICONINFORMATION);}
