bool autostart_enabled(){HKEY key{};if(RegOpenKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",0,KEY_QUERY_VALUE,&key)!=ERROR_SUCCESS)return false;wchar_t value[32768]{};DWORD bytes=sizeof(value),type{};auto result=RegQueryValueExW(key,AUTOSTART_VALUE,nullptr,&type,reinterpret_cast<BYTE*>(value),&bytes);RegCloseKey(key);return result==ERROR_SUCCESS&&type==REG_SZ;}
bool memory_service_ready(){return krmemory::service_rpc::healthy(80);}
bool service_remember(std::string_view title,std::string_view application="user",std::string_view table="manual_memory"){if(title.empty()||title.size()>3072||application.size()>128)return false;std::string response;return krmemory::service_rpc::call("gui-remember","memory.remember","{\"text\":"+krmemory::service_rpc::quote(title)+",\"application\":"+krmemory::service_rpc::quote(application)+",\"table\":"+krmemory::service_rpc::quote(table)+"}",response,500);}
void set_autostart(bool enabled){HKEY key{};if(RegCreateKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",0,nullptr,0,KEY_SET_VALUE,nullptr,&key,nullptr)!=ERROR_SUCCESS)throw std::runtime_error("Cannot update Windows autostart");if(enabled){wchar_t module[32768]{};auto n=GetModuleFileNameW(nullptr,module,32768);if(n==0||n>=32768){RegCloseKey(key);throw std::runtime_error("Cannot resolve executable path");}std::wstring command=L"\""+std::wstring(module,n)+L"\" --background";if(RegSetValueExW(key,AUTOSTART_VALUE,0,REG_SZ,reinterpret_cast<const BYTE*>(command.c_str()),DWORD((command.size()+1)*sizeof(wchar_t)))!=ERROR_SUCCESS){RegCloseKey(key);throw std::runtime_error("Cannot set Windows autostart");}}else RegDeleteValueW(key,AUTOSTART_VALUE);RegCloseKey(key);}

void update_status(){std::wstring s=L"Erfassung: ";s+=(capturing?L"EIN":L"AUS");s+=L"  |  DAD-Attraktoren: "+std::to_wstring(db->attractor_count());s+=L"  |  Agenten: "+std::to_wstring(db->query_sql_like("agent_registry").size());s+=L"  |  Ordner: "+std::to_wstring(folder_roots.size());s+=L"  |  Hintergrundprozess: ";s+=(memory_service_ready()?L"bereit":L"wird gestartet");SetWindowTextW(status,s.c_str());SetWindowTextW(enable,capturing?L"Erfassung stoppen":L"Erfassung starten");}
void save_db(){update_status();}
void list_clear(HWND h){SendMessageW(h,LB_RESETCONTENT,0,0);}
void list_add(HWND h,const std::string& s){auto w=to_wide(krmemory::truncate_utf8(s,700));SendMessageW(h,LB_ADDSTRING,0,reinterpret_cast<LPARAM>(w.c_str()));}
void add_record(std::string table,std::string application,std::string title){if(title.empty())return;title=krmemory::truncate_utf8(std::move(title),3072);if(!service_remember(title,application,table))throw std::runtime_error("Der lokale Gedächtnisdienst ist nicht erreichbar");if(!durable_store)durable_store=std::make_unique<krmemory::MemoryStore>(store_file);*db=durable_store->read();save_db();}
void refresh_table(HWND list,std::string_view table,const char* empty){list_clear(list);auto rows=db->query_sql_like(table);for(const auto& record:rows){auto title=record.data.find("title");auto app=record.data.find("application");std::string v="["+record.table+"] ";if(app!=record.data.end())v+=mycelia::sql::display(app->second)+"  ";if(title!=record.data.end())v+=mycelia::sql::display(title->second);list_add(list,v);}if(rows.empty())list_add(list,empty);}
void refresh_timeline(){list_clear(activity_list);auto records=krmemory::timeline(*db,{}, {},100);for(const auto& record:records){auto title=record.data.find("title");auto stamp=record.data.find("timestamp");std::string item="["+record.table+"] ";if(stamp!=record.data.end())item+=mycelia::sql::display(stamp->second)+"  ";if(title!=record.data.end())item+=mycelia::sql::display(title->second);list_add(activity_list,item);}if(records.empty())list_add(activity_list,"Noch keine chronologischen Aktivitaeten");}
std::string record_field(const mycelia::DynamicAssociativeDatabase::ExternalRecord& record,std::initializer_list<const char*> keys){for(auto key:keys){auto it=record.data.find(key);if(it!=record.data.end()){auto value=mycelia::sql::display(it->second);if(!value.empty())return value;}}return{};}
void refresh_relation_graph(){
    if(!relation_graph||!db)return;
    std::vector<krmemory::RelationGraphNode> nodes;std::vector<krmemory::RelationGraphEdge> edges;std::unordered_set<std::string> known;
    auto kind_of=[](const mycelia::DynamicAssociativeDatabase::ExternalRecord& record){if(record.table=="memory_collections")return std::string("collection");if(record.table=="mcp_agent_permissions"||record.table=="agent_registry")return std::string("agent");if(record.data.contains("source_path")||record.table.find("import")!=std::string::npos||record.table.find("media")!=std::string::npos)return std::string("source");return std::string("memory");};
    auto add_node=[&](const mycelia::DynamicAssociativeDatabase::ExternalRecord& record){if(record.signature.empty()||known.contains(record.signature)||nodes.size()>=16)return false;std::string label=record_field(record,{"title","name","content","agent","application"});if(label.empty())label=record.table;nodes.push_back({to_wide(record.signature),to_wide(krmemory::truncate_utf8(label,34)),to_wide(kind_of(record))});known.insert(record.signature);return true;};
    auto relations=db->query_sql_like("memory_relations",{},80);
    for(const auto& relation:relations){if(nodes.size()>=10)break;auto from=record_field(relation,{"from_signature","from"}),to=record_field(relation,{"to_signature","to"});for(const auto& endpoint:{from,to})if(!endpoint.empty()&&!known.contains(endpoint))if(auto record=db->get_sql_record(endpoint))add_node(*record);}
    auto records=db->query_sql_like({}, {},160);
    auto add_kind=[&](std::string_view wanted,std::size_t maximum){std::size_t added{};for(const auto& record:records){if(nodes.size()>=16||added>=maximum)break;if(record.table!="memory_relations"&&kind_of(record)==wanted&&add_node(record))++added;}};
    add_kind("collection",3);add_kind("source",3);add_kind("memory",6);add_kind("agent",4);
    for(const auto& relation:relations){auto from=record_field(relation,{"from_signature","from"}),to=record_field(relation,{"to_signature","to"});if(known.contains(from)&&known.contains(to)&&edges.size()<28)edges.push_back({to_wide(from),to_wide(to),to_wide(record_field(relation,{"relation_type","type","title"}))});}
    set_relation_graph_data(relation_graph,std::move(nodes),std::move(edges));
}
void update_metrics_text(){if(!metrics_label||!db)return;std::wostringstream out;out.precision(2);out<<std::fixed<<L"DAD-INTEGRITÄT\r\n"<<L"Datensätze  "<<db->external_record_count()<<L" / 50.000\r\n"<<L"Stabilität  "<<db->average_stability()*100.0<<L" %\r\n"<<L"Rauschen    "<<db->noise_factor()*100.0<<L" %";SetWindowTextW(metrics_label,out.str().c_str());}
void refresh_dashboard(){if(durable_store)*db=durable_store->read();refresh_timeline();refresh_table(agent_list,"mcp_agent_permissions","Keine verbundenen KI-Agenten");refresh_table(history_list,"search_history","Noch keine Suchhistorie");if(result_list&&SendMessageW(result_list,LB_GETCOUNT,0,0)==0)list_add(result_list,"Suchbegriff eingeben – Treffer stammen ausschließlich aus der echten DAD");refresh_relation_graph();update_metrics_text();update_status();if(main_window)InvalidateRect(main_window,nullptr,FALSE);}
void show_results(const std::string& cue){list_clear(result_list);list_clear(association_list);auto matches=db->associative_sql_lookup(cue,1.0,50);for(const auto& record:matches){auto value=record.data.find("title");auto kind=record.data.find("application");std::string display="["+record.table+"] ";if(kind!=record.data.end())display+=mycelia::sql::display(kind->second)+"  ";if(value!=record.data.end())display+=mycelia::sql::display(value->second);list_add(result_list,display);list_add(association_list,"-> "+display);}if(matches.empty()){list_add(result_list,"Keine passenden DAD-Datensaetze");list_add(association_list,"Keine assoziativen Verknuepfungen");}if(!cue.empty()){add_record("search_history","user",cue);refresh_dashboard();}else update_status();}
void parse_allowlist(const std::wstring& v){allowed.clear();folder_roots.clear();std::wistringstream ss(v);std::wstring line;while(std::getline(ss,line)){auto a=line.find_first_not_of(L" \t\r");if(a==line.npos)continue;auto b=line.find_last_not_of(L" \t\r");auto raw=to_utf8(line.substr(a,b-a+1));if(raw.rfind("folder:",0)==0){auto root=fs::path(to_wide(raw.substr(7)));if(fs::is_directory(root)&&folder_roots.size()<16)folder_roots.push_back(root);continue;}auto entry=krmemory::normalize_exe(raw);if(!entry.empty()&&allowed.size()<32&&entry.size()<=128)allowed.push_back(entry);}}
void save_preferences(){if(!capturing)stop_collectors();auto temp=prefs_file;temp+=L".tmp";std::ofstream f(temp,std::ios::binary|std::ios::trunc);if(!f)throw std::runtime_error("Cannot write preferences");f<<"3\n"<<(capturing?"1":"0")<<"\n"<<(autostart_enabled()?"1":"0")<<"\n";for(const auto& exe:allowed)f<<"app:"<<exe<<"\n";for(const auto& root:folder_roots)f<<"folder:"<<to_utf8(root.wstring())<<"\n";f.close();if(!f)throw std::runtime_error("Cannot flush preferences");if(!MoveFileExW(temp.c_str(),prefs_file.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Cannot replace preferences");}
void load_preferences(){if(!fs::exists(prefs_file))return;std::ifstream f(prefs_file,std::ios::binary);std::string version,line;std::getline(f,version);if(version=="2"||version=="3"){std::getline(f,line);capturing=line=="1";std::getline(f,line);}allowed.clear();folder_roots.clear();while(std::getline(f,line)){if(version=="3"&&line.rfind("folder:",0)==0){auto root=fs::path(to_wide(line.substr(7)));if(fs::is_directory(root)&&folder_roots.size()<16)folder_roots.push_back(root);continue;}auto exe=krmemory::normalize_exe(version=="3"&&line.rfind("app:",0)==0?line.substr(4):line);if(!exe.empty()&&allowed.size()<32&&exe.size()<=128)allowed.push_back(exe);}}
void start_collectors(){if(!capturing||folder_roots.empty())return;ensure_memory_service();}
void stop_collectors(){if(collector){collector->stop();collector.reset();}}
void add_folder_root(){BROWSEINFOW browse{};browse.hwndOwner=main_window;browse.lpszTitle=L"Ordner fuer die lokale Mycelia-Erfassung freigeben";browse.ulFlags=BIF_RETURNONLYFSDIRS|BIF_NEWDIALOGSTYLE;auto item=SHBrowseForFolderW(&browse);if(!item)return;wchar_t path[MAX_PATH]{};bool resolved=SHGetPathFromIDListW(item,path)!=FALSE;CoTaskMemFree(item);if(!resolved)throw std::runtime_error("Cannot resolve selected folder");auto root=fs::path(path);if(std::find(folder_roots.begin(),folder_roots.end(),root)==folder_roots.end())folder_roots.push_back(root);save_preferences();start_collectors();update_status();}
void tick_capture(){if(!memory_service_ready())ensure_memory_service();if(!capturing){update_status();return;}start_collectors();HWND hwnd=GetForegroundWindow();if(!hwnd||hwnd==main_window)return;wchar_t titlebuf[512]{};if(!GetWindowTextW(hwnd,titlebuf,512))return;DWORD pid{};GetWindowThreadProcessId(hwnd,&pid);if(pid==0)return;HANDLE process=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pid);if(!process)return;wchar_t pathbuf[32768]{};DWORD len=32768;BOOL ok=QueryFullProcessImageNameW(process,0,pathbuf,&len);CloseHandle(process);if(!ok)return;std::string exe=krmemory::normalize_exe(to_utf8(std::wstring(pathbuf,len)));std::string title=to_utf8(titlebuf);if(!krmemory::permitted(exe,title,allowed))return;auto key=exe+"\n"+title;if(key==last_seen)return;last_seen=std::move(key);add_record("windows_context",exe,title);refresh_dashboard();}
void ensure_memory_service(){wchar_t module[32768]{};auto n=GetModuleFileNameW(nullptr,module,32768);if(!n||n>=32768)return;auto service=fs::path(std::wstring(module,n)).parent_path()/L"KR_Mycelia_Service.exe";if(!fs::exists(service))return;std::wstring command=L"\""+service.wstring()+L"\"";STARTUPINFOW startup{sizeof(startup)};PROCESS_INFORMATION process{};if(CreateProcessW(nullptr,command.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,service.parent_path().c_str(),&startup,&process)){CloseHandle(process.hThread);CloseHandle(process.hProcess);}}
void add_tray(){if(tray_visible)return;ensure_memory_service();NOTIFYICONDATAW n{sizeof(n)};n.hWnd=main_window;n.uID=1;n.uFlags=NIF_MESSAGE|NIF_ICON|NIF_TIP;n.uCallbackMessage=WM_TRAY;n.hIcon=LoadIconW(nullptr,IDI_APPLICATION);wcscpy_s(n.szTip,L"KR Mycelia Memory (aktiv im Hintergrund)");tray_visible=Shell_NotifyIconW(NIM_ADD,&n)!=FALSE;}
void remove_tray(){if(!tray_visible)return;NOTIFYICONDATAW n{sizeof(n)};n.hWnd=main_window;n.uID=1;Shell_NotifyIconW(NIM_DELETE,&n);tray_visible=false;}
