int persistence_self_test(){auto test=fs::temp_directory_path()/L"kr_mycelia_windows_persistence_selftest.dpapi";std::error_code ec;int step=1;fs::remove(test,ec);try{mycelia::DynamicAssociativeDatabase test_db(64);mycelia::Pattern pattern;pattern.signature="KR_MYcelia_DAD_PERSISTENCE_OK";pattern.energy_mean=.75;test_db.store_pattern(pattern);mycelia::sql::Row row;row["title"]=std::string("KR Mycelia encrypted DAD row persistence");row["timestamp"]=(std::int64_t)now_epoch();auto signature=test_db.store_sql_record("persistence_self_test",row);step=2;test_db.save_secure_snapshot(test);step=3;auto restored=mycelia::DynamicAssociativeDatabase::load_secure_snapshot(test);step=4;fs::remove(test);auto record=restored.get_pattern(pattern.signature);auto external=restored.get_sql_record(signature);if(!record||record->signature!=pattern.signature)throw std::runtime_error("self-test DAD pattern missing after restore");if(!external||external->table!="persistence_self_test")throw std::runtime_error("self-test DAD record missing after restore");return 0;}catch(...){fs::remove(test,ec);return step;}}
